const requeuePeerRequests = `-- name: RequeuePeerRequests :many
UPDATE peer_requests
SET state = CASE WHEN approval_cycles = 0 THEN 'waiting' ELSE 'approved' END, updated_at = ?1
WHERE state = 'delivered' AND delivered_at <= ?2
  AND (target = ?3 OR ?3 IS NULL)
RETURNING target
`

type RequeuePeerRequestsParams struct {
	Now             int64
	DeliveredBefore *int64
	Target          *string
}

// delivered -> waiting (or approved, for an approved re-run, which is the
// only way a queued request has a round), for one host or all, when the
// push was not claimed: the host said hello again, was busy, its run ended,
// or the claim timed out. Keeps expires_at.
func (q *Queries) RequeuePeerRequests(ctx context.Context, arg RequeuePeerRequestsParams) ([]string, error) {
	rows, err := q.db.QueryContext(ctx, requeuePeerRequests, arg.Now, arg.DeliveredBefore, arg.Target)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var target string
		if err := rows.Scan(&target); err != nil {
			return nil, err
		}
		items = append(items, target)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const reroundPeerRequest = `-- name: ReroundPeerRequest :execrows
UPDATE peer_requests
SET approval_cycles = approval_cycles + 1, fingerprint = ?1, notified_at = NULL, prompt_id = NULL,
    updated_at = ?2
WHERE id = ?3 AND state = 'parked' AND approval_cycles = ?4
`

type ReroundPeerRequestParams struct {
	Fingerprint *string
	Now         int64
	ID          string
	Round       int64
}

// parked at round -> parked at the next round, not prompted yet, with that
// round's fingerprint.
func (q *Queries) ReroundPeerRequest(ctx context.Context, arg ReroundPeerRequestParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, reroundPeerRequest,
		arg.Fingerprint,
		arg.Now,
		arg.ID,
		arg.Round,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

